use IO::Socket::INET;
my %mime=('html','text/html; charset=utf-8','mp4','video/mp4','webp','image/webp','jpg','image/jpeg','png','image/png','css','text/css','js','application/javascript');
my $srv=IO::Socket::INET->new(LocalAddr=>'0.0.0.0',LocalPort=>3000,Listen=>10,ReuseAddr=>1,Proto=>'tcp') or die $!;
$|=1; print "Serving http://localhost:3000\n";
while(1){
  my $c=$srv->accept() or next;
  my $req=''; while(my $l=<$c>){ $req.=$l; last if $l=~/^[\r\n]+$/; }
  my($p)=($req=~/^[A-Z]+\s+(\S+)/); $p//='/';
  $p=~s/\?.*//;
  my $file;
  if($p eq '/' or $p eq '/index.html'){ $file='/tmp/ffb_index.html'; }
  elsif($p eq '/video' or $p eq '/hero.mp4'){ $file='/tmp/ffb_hero.mp4'; }
  elsif($p eq '/hero.png'){ $file='/tmp/ffb_hero.png'; }
  elsif($p eq '/logo.jpg'){ $file='/tmp/ffb_logo.jpg'; }
  else { print $c "HTTP/1.0 404 Not Found\r\n\r\n404"; close $c; next; }
  open my $fh,'<:raw',$file or do{ print $c "HTTP/1.0 403 Forbidden\r\n\r\n$!"; close $c; next; };
  (my $ext=$file)=~s/.*\.//;
  my $ct=$mime{lc($ext)}//'application/octet-stream';
  local $/; my $b=<$fh>; close $fh;
  print $c "HTTP/1.0 200 OK\r\nContent-Type: $ct\r\nContent-Length: ".length($b)."\r\nConnection: close\r\n\r\n".$b;
  close $c;
}
